style.css:
/* Bunny Blush — Roblox */

:root {
  /* change these colors anytime */
  --my-pink: #f4dce4;
  --my-blush: #fbeef1;
  --my-cream: #fffaf7;
  --my-rose: #d5a3b2;
  --my-text: #806b70;
}

/* dreamy pastel background */
body {
  background-color: var(--my-blush) !important;
  color: var(--my-text) !important;
  font-family: "Trebuchet MS", sans-serif !important;
}

/* pink links */
a {
  color: #c58fa1 !important;
}

/* soft buttons */
button {
  border-radius: 14px !important;
  border-color: var(--my-pink) !important;
}

/* rounded search bars */
input,
textarea {
  border-radius: 12px !important;
  border-color: var(--my-rose) !important;
}

/* delicate image corners */
img {
  border-radius: 10px !important;
}

/* bunny decoration */
body::before {
  content: "୨୧ ᕱ⑅ᕱ";
  position: fixed;
  top: 85px;
  right: 22px;
  color: #c58fa1;
  font-size: 23px;
  z-index: 9999;
  pointer-events: none;
}

/* lace-inspired background detail */
body::after {
  content: "";
  position: fixed;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 13px;
  background: repeating-radial-gradient(
    circle at 10px 0,
    #e9c7d2 0 5px,
    transparent 6px 13px
  );
  pointer-events: none;
  z-index: 9998;
}

/* pastel text selection */
::selection {
  background: #eccbd5 !important;
  color: #806b70 !important;
}
